use std::io::{self, Write};

fn report<W: Write>(lines: &[&str], out: &mut W) -> io::Result<()> {
    for (i, line) in lines.iter().enumerate() {
        writeln!(out, "{}: {line}", i + 1)?;
    }
    Ok(())
}

fn main() -> io::Result<()> {
    let mut buffer: Vec<u8> = Vec::new();
    report(&["frog", "bog"], &mut buffer)?;
    assert_eq!(String::from_utf8(buffer).unwrap(), "1: frog\n2: bog\n");

    report(&["printed for real"], &mut io::stdout())?;
    Ok(())
}
